<h2>Scale a laboratory reagent recipe</h2><p class="lead">Scale up or down a multi-component recipe by final batch volume while preserving component ratios.</p><div class="notice">This is ratio scaling. Do not add unlike units together conceptually; the sum display is most meaningful when the listed amounts share the same volume unit.</div><div class="form-grid"><div class="field"><label for="orig">Original recipe final volume</label><input id="orig" type="number" value="100" min="0.000001" step="any"></div><div class="field"><label for="target">Target final volume</label><input id="target" type="number" value="250" min="0.000001" step="any"></div><div class="field"><label for="names">Reagents (one per line)</label><textarea id="names" rows="5">Buffer A
Salt
Additive</textarea></div><div class="field"><label for="amounts">Original amounts, same order</label><textarea id="amounts" rows="5">80
5
2</textarea></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Scale factor</span><strong id="factor">—</strong></div><div class="metric"><span>Sum of listed original amounts</span><strong id="sum">—</strong></div><div class="metric"><span>Sum of scaled listed amounts</span><strong id="scaledsum">—</strong></div><div class="metric"><span>Unlisted make-up volume</span><strong id="unlisted">—</strong></div></div><div class="table-wrap" style="margin-top:14px"><table class="data-table"><thead><tr><th>Reagent</th><th>Original amount</th><th>Scaled amount</th></tr></thead><tbody id="reagentRows"></tbody></table></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('factor').textContent='—';$('sum').textContent='—';$('scaledsum').textContent='—';$('unlisted').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const o=num('orig'),t=num('target');if(!(o>0&&t>0))throw 0;const names=$('names').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),amts=$('amounts').value.split(/\n+/).map(x=>Number(x.trim()));if(names.length===0||amts.length<names.length||amts.slice(0,names.length).some(x=>!Number.isFinite(x)||x<0))throw 0;const f=t/o,sum=amts.slice(0,names.length).reduce((a,b)=>a+b,0);$('factor').textContent=fmt(f,6)+'×';$('sum').textContent=fmt(sum,6);$('scaledsum').textContent=fmt(sum*f,6);$('unlisted').textContent=fmt((o-sum)*f,6);$('reagentRows').innerHTML=names.map((n,i)=>'<tr><td>'+n.replace(/[<>&]/g,'')+'</td><td>'+fmt(amts[i],6)+'</td><td>'+fmt(amts[i]*f,6)+'</td></tr>').join('');$('note').textContent=sum>o?'Listed component amounts exceed the original final volume. Check units and whether solid masses are mixed with liquid volumes.':'All listed amounts are multiplied by target volume ÷ original volume. Keep units for each row unchanged.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
